  if case .num(let x) = a, case .num(let y) = b { return .num(x + y) }
  if let s = text(a) { return .s(s + (try str(b))) }
  return arith(a) ? .num(num(a) + num(b)) : try call(a, "plus", [b])
}
public func sub(_ a: V, _ b: V) throws -> V {
  if case .num(let x) = a, case .num(let y) = b { return .num(x - y) }
  return arith(a) ? .num(num(a) - num(b)) : try call(a, "minus", [b])
}
public func mul(_ a: V, _ b: V) throws -> V {
  if case .num(let x) = a, case .num(let y) = b { return .num(x * y) }
  return arith(a) ? .num(num(a) * num(b)) : try call(a, "times", [b])
}
public func div(_ a: V, _ b: V) throws -> V {
  if !arith(a) { return try call(a, "over", [b]) }
  let x = num(a), y = num(b)
  return .num(y == 0 ? (x == 0 ? 0 : x / y) : x / y)
}
public func mod(_ a: V, _ b: V) throws -> V { return arith(a) ? .num(num(a).truncatingRemainder(dividingBy: num(b))) : try call(a, "mod", [b]) }
public func neg(_ a: V) throws -> V { return arith(a) ? .num(-num(a)) : try get(a, "negated") }
public func power(_ a: V, _ b: V) throws -> V { return arith(a) ? .num(Foundation.pow(num(a), num(b))) : try call(a, "pow", [b]) }
/** `a & b`, `a | b`, `a ?? b`, `c ? a : b`: the right side is read only when it decides */
public func and_(_ a: V, _ b: @autoclosure () throws -> V) rethrows -> V { if !truthy(a) { return a }; return try b() }
public func or_(_ a: V, _ b: @autoclosure () throws -> V) rethrows -> V { if truthy(a) { return a }; return try b() }
public func orElse(_ a: V, _ b: @autoclosure () throws -> V) rethrows -> V { if case .null = a { return try b() }; return a }
public func sel(_ c: Bool, _ a: @autoclosure () throws -> V, _ b: @autoclosure () throws -> V) rethrows -> V { return c ? try a() : try b() }
public func not(_ a: V) -> V { return .b(!truthy(a)) }

/** a number as the bootstrap (JavaScript) writes it: whole numbers without a point, the shortest digits that read back */
public func numberText(_ d: Double) -> String {
  if d.isNaN { return "NaN" }
  if d.isInfinite { return d > 0 ? "Infinity" : "-Infinity" }
  if d == 0 { return "0" }
  if d == d.rounded() && Swift.abs(d) < 1e21 { return String(Int64(d)) }
  let neg = d < 0
  var t = Swift.abs(d).description // Swift's shortest digits: "0.001", "1.5e-07", "1.2e+16"
  var e10 = 0
  if let i = t.firstIndex(where: { $0 == "e" || $0 == "E" }) { e10 = Int(t[t.index(after: i)...]) ?? 0; t = String(t[..<i]) }
  var intPart = t, frac = ""
  if let p = t.firstIndex(of: ".") { intPart = String(t[..<p]); frac = String(t[t.index(after: p)...]) }
  var digits = intPart + frac
  var n = intPart.count + e10 // the point sits after n digits
  while digits.hasPrefix("0") && digits.count > 1 { digits.removeFirst(); n -= 1 }
  while digits.hasSuffix("0") && digits.count > 1 { digits.removeLast() }
  let k = digits.count
  var out: String
  if k <= n && n <= 21 { out = digits + String(repeating: "0", count: n - k) }
  else if 0 < n && n <= 21 { out = String(digits.prefix(n)) + "." + String(digits.dropFirst(n)) }
  else if -6 < n && n <= 0 { out = "0." + String(repeating: "0", count: -n) + digits }
  else {
    let e = n - 1
    let m = k == 1 ? digits : String(digits.prefix(1)) + "." + String(digits.dropFirst(1))
    out = m + "e" + (e >= 0 ? "+" : "-") + String(Swift.abs(e))
  }
  return neg ? "-" + out : out
}
public func str(_ x: V) throws -> String {
  switch x {
  case .null: return "null"
  case .num(let d): return numberText(d)
  case .b(let b): return b ? "true" : "false"
  case .s(let s): return s
  case .list(let l): return try l.a.map { try str($0) }.joined(separator: ",")
  case .fn: return "function"
  case .obj(let o): return o.cls.findMethod(Name("toString").id) != nil ? try str(try call(x, "toString", [])) : o.cls.name
  case .many(let m): return try m.items.map { try str($0) }.joined(separator: ",")
  case .cls(let c): return c.name
  case .kw(let k): return "\(k.name.text): \(try str(k.value))"
  }
}

// --- lists and text -------------------------------------------------------------------------------
public func list(_ xs: V...) -> V { return .list(L(xs)) }
public func items(_ xs: V) throws -> [V] {
  switch xs {
  case .list(let l): return l.a
  case .many(let m): return m.items
  case .s(let s): return s.unicodeScalars.map { V.s(String($0)) }
  case .null: return []
  default: throw RayError("not a list: \(kindName(xs))")
  }
}
func units(_ s: String) -> [UInt16] { return Array(s.utf16) }
func fromUnits<S: Sequence>(_ u: S) -> String where S.Element == UInt16 { return String(decoding: Array(u), as: UTF16.self) }
public func len(_ xs: V) throws -> V {
  switch xs {
  case .list(let l): return .num(Double(l.a.count))
  case .s(let s): return .num(Double(s.utf16.count))
  case .many(let m): return .num(Double(m.items.count))
  default: return try get(xs, "length")
  }
}
/** an index as a list reads it: a whole number, or none */
func index(_ k: V) -> Int? { let d = num(k); if !d.isFinite || d != d.rounded(.towardZero) || Swift.abs(d) > 1e15 { return nil }; return Int(d) }
public func elem(_ t: V, _ k: V) throws -> V {
  switch t {
  case .list(let l):
    guard var i = index(k) else { return .null }
    if i < 0 { i += l.a.count }
    return i >= 0 && i < l.a.count ? l.a[i] : .null
  case .null: return .null
  case .s(let s):
    guard var i = index(k) else { return .null }
    let u = units(s)
    if i < 0 { i += u.count }
    return i >= 0 && i < u.count ? .s(fromUnits([u[i]])) : .null
  case .many(let m): return collapse(try m.items.map { try elem($0, k) })
  case .obj, .cls: if case .s(let n) = k { return try get(t, Name(n)) }; return try get(t, Name(try str(k)))
  default: return .null
  }
}
@discardableResult
public func setAt(_ t: V, _ k: V, _ v: V) throws -> V {
  if case .list(let l) = t {
    guard let i = index(k), i >= 0 else { throw RayError("no place \(try str(k)) in a list") }
    while l.a.count <= i { l.a.append(.null) }
    l.a[i] = v
    return v
  }
  if case .s(let n) = k { return try set(t, Name(n), v) }
  return try set(t, Name(try str(k)), v)
}
public func filt(_ xs: V, _ f: V) throws -> V {
  var out: [V] = []
  for x in try items(xs) { if truthy(try invoke(f, [x])) { out.append(x) } }
  if case .many = xs { return .many(Many(out)) }
  return .list(L(out))
}
func count(_ n: V) -> Int { let d = num(n); if !d.isFinite || d <= 0 { return 0 }; return Int(d) }
public func rng(_ n: V) -> V { let k = count(n); var out: [V] = []; out.reserveCapacity(k); for i in 0..<k { out.append(.num(Double(i))) }; return .list(L(out)) }
public func filled(_ n: V, _ v: V) -> V { return .list(L(Array(repeating: v, count: count(n)))) }
public func first(_ xs: V) throws -> V { if case .s(let s) = xs { return s.isEmpty ? .null : .s(String(s.unicodeScalars.first!)) }; let l = try items(xs); return l.isEmpty ? .null : l[0] }
public func last(_ xs: V) throws -> V { if case .s(let s) = xs { return s.isEmpty ? .null : .s(String(s.unicodeScalars.last!)) }; let l = try items(xs); return l.isEmpty ? .null : l[l.count - 1] }
public func quoted(_ x: V) throws -> V {
  let s = try str(x)
  var out = "\""
  for u in s.unicodeScalars {
    switch u {
    case "\"": out += "\\\""
    case "\\": out += "\\\\"
    case "\n": out += "\\n"
    case "\r": out += "\\r"
    case "\t": out += "\\t"
    default:
      if u.value < 0x20 { out += String(format: "\\u%04x", u.value) } else { out.unicodeScalars.append(u) }
    }
  }
  return .s(out + "\"")
}
public func fail_(_ says: V) throws -> V { throw RayError(try str(says)) }
public func fromCodepoints(_ xs: V) throws -> V {
  var out = String.UnicodeScalarView()
  for c in try items(xs) { if let u = Unicode.Scalar(UInt32(max(0, num(c)))) { out.append(u) } }
  return .s(String(out))
}
public func blank(_ c: V) -> V { let d = num(c); return .b(d == 32 || d == 9 || d == 10 || d == 13) }
public func number(_ s: V) throws -> V {
  let t = (try str(s)).trimmingCharacters(in: .whitespacesAndNewlines)
  if t == "Infinity" || t == "+Infinity" { return .num(Double.infinity) }
  if t == "-Infinity" { return .num(-Double.infinity) }
  if t.lowercased().contains("inf") || t.lowercased().contains("nan") && t != "NaN" { return .num(Double.nan) }
  return .num(Double(t) ?? Double.nan)
}

/** a member Ray knows on a list, a text or a number - and any object's own member of that name otherwise (`Expr.split(e, name)`) */
@inline(__always) func core(_ x: V) -> Bool {
  switch x { case .obj, .cls, .fn, .kw: return false; default: return true }
}
func listOf(_ xs: V) throws -> L { if case .list(let l) = xs { return l }; throw RayError("not a list: \(kindName(xs))") }
@discardableResult
public func m_push(_ xs: V, _ x: V) throws -> V { if core(xs) { try listOf(xs).a.append(x); return xs }; return try call(xs, "push", [x]) }
public func m_chars(_ xs: V) throws -> V { if case .s(let s) = xs { return .list(L(s.unicodeScalars.map { V.num(Double($0.value)) })) }; return try get(xs, "chars") }
@discardableResult
public func m_pop(_ xs: V) throws -> V { if core(xs) { let l = try listOf(xs); return l.a.isEmpty ? .null : l.a.removeLast() }; return try get(xs, "pop") }
public func m_map(_ xs: V, _ f: V) throws -> V {
  if !core(xs) { return try call(xs, "map", [f]) }
  let l = try items(xs); var out: [V] = []; out.reserveCapacity(l.count)
  for x in l { out.append(try invoke(f, [x])) }
  return .list(L(out))
}
@discardableResult
public func m_for(_ xs: V, _ f: V) throws -> V { if !core(xs) { return try call(xs, "for", [f]) }; for x in try items(xs) { try invoke(f, [x]) }; return .null }
public func m_some(_ xs: V, _ f: V) throws -> V { if !core(xs) { return try call(xs, "some", [f]) }; for x in try items(xs) { if truthy(try invoke(f, [x])) { return .b(true) } }; return .b(false) }
public func m_every(_ xs: V, _ f: V) throws -> V { if !core(xs) { return try call(xs, "every", [f]) }; for x in try items(xs) { if !truthy(try invoke(f, [x])) { return .b(false) } }; return .b(true) }
public func m_reduce(_ xs: V, _ z: V, _ f: V) throws -> V { if !core(xs) { return try call(xs, "reduce", [z, f]) }; var acc = z; for x in try items(xs) { acc = try invoke(f, [acc, x]) }; return acc }
public func m_starts_with(_ xs: V, _ x: V) throws -> V { if core(xs) { return .b((text(xs) ?? "").hasPrefix(try str(x))) }; return try call(xs, "starts_with", [x]) }
public func m_ends_with(_ xs: V, _ x: V) throws -> V { if core(xs) { return .b((text(xs) ?? "").hasSuffix(try str(x))) }; return try call(xs, "ends_with", [x]) }
public func m_replace(_ xs: V, _ x: V, _ y: V) throws -> V {
  if !core(xs) { return try call(xs, "replace", [x, y]) }
  let s = text(xs) ?? "", a = try str(x), b = try str(y)
  if a.isEmpty { return .s(s) }
  return .s(s.replacingOccurrences(of: a, with: b))
}
public func m_split(_ xs: V, _ x: V, _ more: V...) throws -> V {
  if !core(xs) { return try call(xs, "split", [x] + more) }
  let s = text(xs) ?? "", sep = try str(x)
  if sep.isEmpty { return .list(L(try items(.s(s)))) }
  return .list(L(s.components(separatedBy: sep).map { V.s($0) }))
}
public func m_trim(_ xs: V) throws -> V { if core(xs) { return .s((text(xs) ?? "").trimmingCharacters(in: .whitespacesAndNewlines)) }; return try get(xs, "trim") }
public func m_upper(_ xs: V) throws -> V { if core(xs) { return .s((text(xs) ?? "").uppercased()) }; return try get(xs, "upper") }
public func m_lower(_ xs: V) throws -> V { if core(xs) { return .s((text(xs) ?? "").lowercased()) }; return try get(xs, "lower") }
public func m_lines(_ xs: V) throws -> V { if core(xs) { return try m_split(xs, .s("\n")) }; return try get(xs, "lines") }
public func m_contains(_ xs: V, _ x: V) throws -> V {
  if !core(xs) { return try call(xs, "contains", [x]) }
  if case .s(let s) = xs { let t = try str(x); return .b(t.isEmpty || s.range(of: t) != nil) }
  for y in try items(xs) { if try eq(y, x) { return .b(true) } }
  return .b(false)
}
public func m_index_of(_ xs: V, _ x: V) throws -> V {
  if !core(xs) { return try call(xs, "index_of", [x]) }
  if case .s(let s) = xs {
    let t = try str(x)
    if t.isEmpty { return .num(0) }
    guard let r = s.range(of: t) else { return .null }
    return .num(Double(s.utf16.distance(from: s.utf16.startIndex, to: r.lowerBound.samePosition(in: s.utf16) ?? s.utf16.startIndex)))
  }
  let l = try items(xs)
  for i in 0..<l.count { if try eq(l[i], x) { return .num(Double(i)) } }
  return .null
}
public func m_join(_ xs: V, _ sep: V) throws -> V { if !core(xs) { return try call(xs, "join", [sep]) }; let s = try str(sep); return .s(try items(xs).map { try str($0) }.joined(separator: s)) }
public func m_first(_ xs: V) throws -> V { return core(xs) ? try first(xs) : try get(xs, "first") }
public func m_last(_ xs: V) throws -> V { return core(xs) ? try last(xs) : try get(xs, "last") }
public func m_empty(_ xs: V) throws -> V { return core(xs) ? .b(num(try len(xs)) == 0) : try get(xs, "empty") }
public func m_take(_ xs: V, _ n: V) throws -> V {
  if !core(xs) { return try call(xs, "take", [n]) }
  let k = count(n)
  if case .s(let s) = xs { return .s(fromUnits(units(s).prefix(k))) }
  return .list(L(Array(try items(xs).prefix(k))))
}
public func m_drop(_ xs: V, _ n: V) throws -> V {
  if !core(xs) { return try call(xs, "drop", [n]) }
  let k = count(n)
  if case .s(let s) = xs { return .s(fromUnits(units(s).dropFirst(k))) }
  return .list(L(Array(try items(xs).dropFirst(k))))
}
public func m_rest(_ xs: V) throws -> V { return core(xs) ? try m_drop(xs, .num(1)) : try get(xs, "rest") }
public func m_concat(_ xs: V, _ ys: V) throws -> V {
  if !core(xs) { return try call(xs, "concat", [ys]) }
  if case .s(let s) = xs { return .s(s + (try str(ys))) }
  return .list(L(try items(xs) + (try items(ys))))
}
public func m_reverse(_ xs: V) throws -> V {
  if !core(xs) { return try get(xs, "reverse") }
  if case .s(let s) = xs { return .s(String(s.reversed())) }
  return .list(L(try items(xs).reversed()))
}
public func m_sum(_ xs: V) throws -> V { if !core(xs) { return try get(xs, "sum") }; var s = 0.0; for x in try items(xs) { s += num(x) }; return .num(s) }
public func m_most(_ xs: V, _ key: V) throws -> V {
  if !core(xs) { return try call(xs, "most", [key]) }
  var best: V? = nil, at = -1, bk = -Double.infinity
  let l = try items(xs)
  for i in 0..<l.count { let k = num(try invoke(key, [l[i]])); if best == nil || k > bk { best = l[i]; at = i; bk = k } }
  guard let b = best else { return .null }
  return list(b, .num(Double(at)))
}
public func m_sorted_by(_ xs: V, _ key: V) throws -> V {
  if !core(xs) { return try call(xs, "sorted_by", [key]) }
  let l = try items(xs)
  var ks: [Double] = []
  for x in l { ks.append(num(try invoke(key, [x]))) }
  let idx = (0..<l.count).sorted { p, q in ks[p] != ks[q] ? ks[p] < ks[q] : p < q }
  return .list(L(idx.map { l[$0] }))
}
public func m_each(_ xs: V) throws -> V { return core(xs) ? .many(Many(try items(xs))) : try get(xs, "each") }
public func m_sqrt(_ x: V) throws -> V { return arith(x) ? .num(num(x).squareRoot()) : try get(x, "sqrt") }
public func m_floor(_ x: V) throws -> V { return arith(x) ? .num(num(x).rounded(.down)) : try get(x, "floor") }
public func m_abs(_ x: V) throws -> V { return arith(x) ? .num(Swift.abs(num(x))) : try get(x, "abs") }
public func m_magnitude(_ x: V) throws -> V { return arith(x) ? .num(Swift.abs(num(x))) : try get(x, "magnitude") }
public func m_cos(_ x: V) throws -> V { return arith(x) ? .num(Foundation.cos(num(x))) : try get(x, "cos") }
public func m_sin(_ x: V) throws -> V { return arith(x) ? .num(Foundation.sin(num(x))) : try get(x, "sin") }
public func m_round(_ x: V) throws -> V { return arith(x) ? .num((num(x) + 0.5).rounded(.down)) : try get(x, "round") }
public func m_ln(_ x: V) throws -> V { return arith(x) ? .num(Foundation.log(num(x))) : try get(x, "ln") }
public func m_exp(_ x: V) throws -> V { return arith(x) ? .num(Foundation.exp(num(x))) : try get(x, "exp") }
public func m_atan2(_ x: V, _ y: V) throws -> V { return arith(x) ? .num(Foundation.atan2(num(x), num(y))) : try call(x, "atan2", [y]) }
public func m_pow(_ x: V, _ y: V) throws -> V { return arith(x) ? .num(Foundation.pow(num(x), num(y))) : try call(x, "pow", [y]) }

// --- the Many: a superposition; members apply elementwise, equal things collapse ---------------------
public final class Many {
  public var items: [V]
  public init(_ items: [V]) { self.items = items }
  func get(_ n: Name) throws -> V { var out: [V] = []; for x in items { if case .null = x { out.append(.null) } else { out.append(try OrbitMinesPhysics.get(x, n)) } }; return collapse(out) }
  func call(_ n: Name, _ a: [V]) throws -> V { var out: [V] = []; for x in items { out.append(try OrbitMinesPhysics.call(x, n, a)) }; return collapse(out) }
}
public func many(_ xs: V) throws -> V { return .many(Many(try items(xs))) }
/** the same thing, as JavaScript's `===` reads it: a number, a text or a boolean by its value, anything else by its identity */
func same(_ a: V, _ b: V) -> Bool {
  switch (a, b) {
  case (.null, .null): return true
  case (.num(let x), .num(let y)): return x == y
  case (.s(let x), .s(let y)): return x == y
  case (.b(let x), .b(let y)): return x == y
  case (.list(let x), .list(let y)): return x === y || ((try? eq(a, b)) ?? false)
  case (.obj(let x), .obj(let y)): return x === y
  case (.many(let x), .many(let y)): return x === y
  case (.cls(let x), .cls(let y)): return x === y
  default: return false
  }
}
public func collapse(_ items: [V]) -> V {
  if items.isEmpty { return .many(Many(items)) }
  let f = items[0]
  for i in items { if !same(i, f) { return .many(Many(items)) } }
  return f
}

/** a text with its interpolations: `"a {x} b"` is `cat("a ", try str(x), " b")` - one call, whatever the lines inside */
@inline(__always) public func cat(_ a: String) -> String { return a }
public func cat(_ parts: String...) -> String { return parts.joined() }
